import type { HTMLAttributes } from 'react';
import { cx } from '@/lib/cx';
import './sheet.css';

/**
 * B2 · Sheet — the platinum wall the paper sits on. The first child row
 * gets data-overlap: margin-top -44px, pinning paper over the band edge.
 * Exactly ONE overlap row per page — a signature, not a repeating trick.
 */
export function Sheet({ className, children, ...rest }: HTMLAttributes<HTMLElement>) {
  return (
    <main {...rest} id="sv-content" className={cx('sv-sheet', className)}>
      {children}
    </main>
  );
}

/** 12-col grid row, 14px gutters. Use the canonical splits. */
export interface RowProps extends HTMLAttributes<HTMLDivElement> {
  /** 'stats' = repeat(4,1fr) (2×2 below 1000px) · 'main' = 1.7fr/1fr · 'full'. */
  split?: 'stats' | 'main' | 'full';
  /** The single overlap row that pins over the band. */
  overlap?: boolean;
  /**
   * v0.5 · the public surface. A dashboard's rows are one dense stack of
   * work, 14px apart; a public page is a sequence of arguments, and 14px
   * between two of them reads as one long argument. `section` is the break
   * between arguments — it exists for the marketing surface and a product
   * screen has no use for it.
   */
  space?: 'row' | 'section';
}

export function Row({
  split = 'full',
  overlap = false,
  space = 'row',
  className,
  children,
  ...rest
}: RowProps) {
  return (
    <div
      {...rest}
      className={cx('sv-row', `sv-row--${split}`, space === 'section' && 'sv-row--break', className)}
      data-overlap={overlap || undefined}
    >
      {children}
    </div>
  );
}

/* B2 · Sheet & Grid */

@layer sv-components {
  .sv-sheet {
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 var(--sv-s8) var(--sv-s8);
  }

  @media (max-width: 1000px) {
    .sv-sheet {
      padding: 0 18px 18px;
    }
  }

  .sv-row {
    display: grid;
    gap: 14px;
    margin-top: 14px;
  }

  /* The 76° signature move: paper pinned over the band edge. */
  .sv-row[data-overlap] {
    margin-top: -44px;
  }

  /* v0.5 · the section break, for the public surface only. 14px separates two
     cards of one dashboard; it does not separate two arguments of one page.
     The overlap rule above still wins on the one row that carries it — it is
     an attribute selector and this is a class — so a break can never cancel
     the signature move by accident. */
  .sv-row--break {
    margin-top: calc(var(--sv-s8) + var(--sv-s6));
  }

  @media (max-width: 1000px) {
    .sv-row--break {
      margin-top: var(--sv-s8);
    }
  }

  /* minmax(0, …) on every track, never a bare 1fr: a grid item's default
     min-width is auto, so one wide table or one long tabular figure widens
     its own column and pushes the page into a horizontal scroll. Ship Gate
     point 11 requires the zero floor, and the C7 320px floor depends on it. */
  .sv-row--stats {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .sv-row--main {
    grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr);
  }

  .sv-row--full {
    grid-template-columns: minmax(0, 1fr);
  }

  @media (max-width: 1000px) {
    .sv-row--stats {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .sv-row--main {
      grid-template-columns: minmax(0, 1fr);
    }
  }

  /* The S1 anatomy does not compress below about 200px — a 34px tile, a
     24px value and a delta chip on one row need the width they need. Two
     columns of 141px would truncate the numbers, so the row goes single
     file instead. Nothing is hidden and nothing scrolls (C7). */
  @media (max-width: 560px) {
    .sv-row--stats {
      grid-template-columns: minmax(0, 1fr);
    }
  }
}
